import {caseQuestions} from './omics-case-questions.js';
// Pedagogical pipelines are conceptual, not executable processing prescriptions.
const d=(input,workflow,result,qc,compare,ref,lab)=>({input,workflow:workflow.split(' → '),result,qc:qc.split('；'),compare,ref,lab});
export const analysis={
 genomics:d('FASTQ + 参考 FASTA + 样本表','检查读段质量、接头及污染 → 比对并检查覆盖与重复 → 调用候选 SNV / indel / SV → 过滤、注释并结合遗传背景解释','BAM/CRAM 保存比对；VCF 保存候选变异及质量字段。','检查测序深度与覆盖均匀性；区分胚系和体细胞分析设计；低复杂度与重复区域可能多重比对','WGS 覆盖更广，WES 聚焦捕获区域；长短读长是另一个选择维度。','variant','variant'),
 epigenomics:d('ATAC / ChIP / CUT&Tag 读段 + 对照信息','核对各实验测量靶标 → 比对并检查富集与背景 → 生成轨迹与候选峰集合 → 比较区域信号并关联候选调控','BED / narrowPeak / broadPeak 表示区域；bigWig 表示连续信号。','检查抗体特异性与实验对照；匹配峰宽模型和靶标；结合批次与重复一致性','ATAC 测可及性，ChIP / CUT&Tag 测靶标关联位置；它们不是同一信号的替代品。','atac','peaks'),
 transcriptomics:d('RNA-seq FASTQ + GTF + 分组和批次表','检查链特异性与 rRNA 残留 → 比对或转录本定量 → 汇总基因计数并检查样本关系 → 建立设计矩阵后进行差异及通路分析','基因×样本原始计数；差异表含效应量、P 值与校正 P 值。','独立生物学重复优先；确认样本编号与设计不混杂；DESeq2 等计数模型不能直接输入 TPM 当原始计数','基因定量适合丰度比较；转录本与剪接分析还需异构体层信息。','rnaseq','counts'),
 proteomics:d('RAW / mzML + 蛋白 FASTA + 样本设计','检查仪器及色谱质量 → 搜库或适配 DIA 鉴定 → 控制错误率并处理共享肽 → 汇总蛋白、归一化并比较条件','PSM、肽段与蛋白定量表；不同层级的 FDR 分别解释。','检查定量缺失与批次；共享肽影响蛋白归属；鉴定错误率不等于差异分析错误率','DDA / DIA 决定采集方式，TMT / SILAC 决定标记方式，不能放在同一互斥列表中。','ms','peptides'),
 metabolomics:d('质谱 RAW / mzML + 空白 + QC + 标准品信息','检测色谱峰并校正保留时间 → 对齐特征并检查空白背景 → 注释加合物、同位素与碎片 → 进行定量比较和通路解释','特征表以 m/z、保留时间和强度定位；鉴定后再赋予化合物名称。','检查 QC 样本漂移；空白污染峰需要识别；明确鉴定等级而非把特征直接命名','靶向分析验证预设物，非靶向分析扩大候选覆盖；标准品可提高身份确认与定量可信度。','xcms','features'),
 pangenomics:d('多个基因组组装 + 样本来源与注释','评估组装完整度和污染 → 比较同源区域与基因存在缺失 → 构建共同骨架与变异路径 → 检查参考偏倚并关联群体特征','基因存在/缺失矩阵或 GFA 图路径；样本范围决定可描述的多样性。','低质量组装可能产生假缺失；同源判定阈值影响核心基因集合；代表性采样影响图覆盖','基因簇泛基因组强调基因有无；序列图泛基因组还能表示等位路径与结构差异。','variant','presence'),
 'cancer-genomics':d('肿瘤与匹配正常 FASTQ + 临床研究元数据','核对肿瘤正常配对及污染 → 分别比对并检查覆盖 → 调用体细胞变异与 CNV → 结合纯度、倍性与证据注释','VCF、分段拷贝数和 VAF；每个值有其分母与模型假设。','确认肿瘤纯度和测序深度；处理胚系及技术伪影；独立验证复杂重排与低频候选','仅肿瘤分析与配对正常分析证据条件不同；低 VAF 不能直接等同小亚克隆。','variant','variant'),
 methylomics:d('转化测序 FASTQ + 参考 + 转化对照','检查转化率与文库质量 → 按转化规则比对 → 统计每个位点的甲基化及总覆盖 → 按设计比较 DMP / DMR','CpG 位点比例与区域差异；beta 值分母来自有效覆盖或芯片信号。','低覆盖比例不稳定；控制转化不完全与比对偏差；组织细胞组成可能改变总体比例','WGBS、RRBS 和芯片覆盖不同；传统亚硫酸氢盐法通常不能直接区分 5mC 与 5hmC。','methyl','methyl'),
 chromatinomics:d('ATAC / MNase 片段 + 基因组注释','检查核质量及片段长度 → 比对、去除不合适片段 → 识别开放区或核小体相关位置 → 结合 TSS / motif / RNA 解释','开放峰、切割轨迹与片段长度分布；核小体占用与可及性需分开。','TSS 富集反映一类信噪信息；FRiP 依赖峰集合；MNase 消化程度影响图谱','ATAC 倾向记录可接近区域，MNase 通过保护片段研究核小体，两者实验偏好不同。','atac','peaks'),
 'threed-genomics':d('Hi-C 配对读段 + 染色体信息','识别有效配对及连接伪影 → 将两端映射到基因组坐标 → 分箱并校正接触矩阵 → 研究区室、结构域与候选环','pairs / cooler / hic 与接触热图；bin 大小决定展示粒度。','检查 cis/trans 与重复率；低覆盖 bin 会影响平衡；距离衰减是接触背景的重要部分','Hi-C 观察全局接触，Capture-C 聚焦目标；高分辨率需要足够有效接触数。','hic','contact'),
 epitranscriptomics:d('IP 与 input RNA 测序 + 重复与对照','检查输入丰度和富集质量 → 将片段定位到转录组或基因组 → 结合 input 识别富集区域 → 区分 RNA 总量变化与修饰变化','修饰富集区域或适配方法的位点表；区域信号不自动提供占有率。','检查抗体或化学反应背景；输入 RNA 量影响 IP 信号；不同修饰需要适配检测方法','MeRIP 常提供区域级富集；位点级方法的覆盖、适用修饰与定量能力依具体原理而异。','rnaseq','enrichment'),
 translatomics:d('Ribo-seq + 匹配 RNA-seq + 注释','检查片段长度及 rRNA 污染 → 比对并估计核糖体位置 → 检查三核苷酸周期与 ORF → 联合 RNA 解释相对翻译效率','足迹覆盖、ORF 和相对翻译效率；占用还受停顿和延长速度影响。','核糖体保护片段长度需核对；周期性与起止位点检查；RNA 与 Ribo 的样本和时间应匹配','Ribo-seq 解析足迹分布，polysome profiling 观察负载组分；两者分辨率不同。','rnaseq','occupancy'),
 regulomics:d('ATAC / ChIP / RNA + motif 与干预信息','统一样本身份和基因组版本 → 识别调控区域与候选结合因子 → 将区域连接到候选靶基因 → 用干预或独立数据检验网络边','调控元件—因子—基因候选网络；边必须注明证据。','motif 相同不保证同一因子结合；邻近基因不一定是真靶基因；批次和细胞组成可能制造关联','共表达提出候选边，结合实验提供占位证据，CRISPR 干预检验功能。','signac','network'),
 'isoform-omics':d('短或长读长 RNA + 注释 + 条件设计','检查接头、完整性及错误模式 → 定位外显子与剪接连接 → 重建或定量转录本 → 比较异构体使用与剪接事件','GTF 转录本结构、junction 计数、PSI 与异构体丰度。','排除内部引物和连接伪影；新转录本需要多分子支持；区分基因总量和转录本比例','长读长连接远端事件，短读长可支持高深度局部剪接；两种信息可以互补。','iso','splicing'),
 'smallrna-omics':d('small RNA FASTQ + 接头 + 分类注释','去接头并检查长度分布 → 处理污染与多重比对 → 定量成熟 miRNA / isomiR 等 → 比较条件并提出靶标候选','序列或 miRNA×样本计数，附长度和注释类别。','接头残留会改变比对；不同类别长度分布不同；多重比对规则影响重复来源 RNA','small RNA-seq 用于发现和定量；靶向检测适合复核，靶标预测还需要功能证据。','small','lengths'),
 phosphoproteomics:d('磷酸肽富集 MS + 总蛋白组','鉴定肽段并控制错误率 → 评估修饰位点定位置信度 → 结合总蛋白校正位点变化 → 提出激酶和通路活性线索','蛋白位点×样本信号与定位概率；富集量不是修饰占有率。','总蛋白变化会影响位点信号；一个肽可能含多个候选位点；富集效率与缺失需检查','总蛋白组关注载体量，磷酸化组关注位点；激酶活性推断依赖底物集合与假设。','ms','ptm'),
 glycomics:d('释放糖链 MS / 色谱 + 标准或酶学信息','识别糖链特征 → 根据质量与碎片提出组成 → 结合酶学或保留信息区分结构 → 比较糖型并报告鉴定层级','糖链组成与结构候选表；同组成异构体可能未完全区分。','释放与衍生化效率影响信号；异构体可能共洗脱；区分组成鉴定和结构确认','释放糖链可集中研究糖谱；完整糖肽能保留载体和位点，回答的问题不同。','ms','features'),
 glycoproteomics:d('完整糖肽谱 + 蛋白/糖链数据库','富集并采集糖肽碎片 → 联合识别肽段和糖链 → 检查位点及组合置信度 → 比较位点糖型分布','蛋白—位点—糖型三元记录；不要只汇总成一个总糖信号。','肽段与糖链置信度需区分；搜索空间增加会影响错误控制；位点信号也受载体量影响','去糖分析利于定位部分位点；完整糖肽进一步连接原始糖型。','ms','ptm'),
 interactomics:d('AP–MS / 邻近标记 + 阴性对照','检查诱饵表达和富集 → 识别候选伙伴及背景 → 根据重复和对照评估富集 → 建网并用正交实验验证','诱饵—伙伴关系表；注明共复合物、邻近或直接结合证据。','常见污染蛋白需识别；裂解可能丢失弱相互作用；表达量变化会影响富集','AP–MS 与邻近标记的捕获条件不同；结构或结合实验能补充直接性证据。','ms','network'),
 'structural-proteomics':d('结构数据 / 交联肽 / HDX + 模型信息','检查样品与数据质量 → 识别空间或交换约束 → 构建并评估结构/构象模型 → 与功能及独立约束交叉验证','坐标模型、距离约束或交换曲线；预测与实测要标注来源。','覆盖不均影响可解释区域；低置信区域不宜过度解释；构象异质性可能被平均','交联给距离约束，HDX 给交换与可及性线索；电镜或晶体学提供另一类结构信息。','ms','network'),
 secretomics:d('条件培养液 / 体液 MS + 培养基空白','检查细胞活性和培养背景 → 分离胞外组分并鉴定 → 校正细胞量及技术差异 → 比较分泌相关候选并验证来源','胞外蛋白及囊泡货物定量；来源可能包括主动释放和损伤。','培养基蛋白背景；细胞死亡与数量；囊泡分离纯度','可溶分泌蛋白与胞外囊泡需要不同分离策略；体液信号还整合多组织来源。','ms','peptides'),
 ubiquitinomics:d('K-ε-GG 肽段富集 + 总蛋白信息','识别特征残基肽段 → 评估位点定位与背景 → 结合总蛋白比较修饰 → 用链型和功能实验细化解释','候选修饰位点与相对量；一般不能还原完整泛素链结构。','泛素样修饰可能贡献残基；载体量变化需区分；链型信息不由普通残基肽自动给出','位点富集与链型检测互补；泛素化可涉及降解、运输或其他调控。','ms','ptm'),
 acetylomics:d('乙酰肽 MS 或组蛋白靶标测序','先确认是蛋白还是基因组坐标 → 对应地鉴定位点或富集区域 → 结合总蛋白或输入背景 → 比较修饰与功能相关变化','质谱给蛋白位点；ChIP / CUT&Tag 给靶标相关基因组区域。','富集抗体偏好；位点定位概率；总蛋白与修饰量关系','蛋白质谱的位点表不能直接代替组蛋白标记的基因组轨迹。','ms','ptm'),
 peptidomics:d('未统一酶切的内源肽 MS + 采样信息','快速控制降解与前处理 → 搜索天然肽序列和末端 → 结合前体定位加工片段 → 比较成熟肽及候选加工模式','内源肽序列、末端、修饰与定量表。','采样后水解；搜索参数要适配非标准酶切；低丰度及基质影响检出','肽组测天然片段，bottom-up 蛋白组通常主动消化；二者的肽来源不同。','ms','peptides'),
 lipidomics:d('脂质 MS / MS/MS + 内标 + QC','提取并识别脂质特征 → 利用碎片推断类别及链组成 → 校正内标和批次 → 按鉴定层级比较脂质分子种','类别、总碳双键数或链级注释；双键位置常需额外证据。','不同类别响应系数不同；异构体与同量异位素干扰；绝对定量需校准','总组成注释与 sn 位点、双键位置解析并非同一层级。','xcms','features'),
 fluxomics:d('稳定同位素时间序列 + 代谢网络','校正天然同位素与检测偏差 → 计算质量同位素分布 MID → 结合网络和稳态假设拟合 → 检查可辨识性及通量不确定性','同位素分布、拟合通量与区间；不是浓度表的简单替代。','示踪时间设计；同位素纯度和自然丰度；网络约束与模型可辨识性','稳态与非稳态分析假设不同；同样浓度可以对应不同通量。','xcms','flux'),
 ionomics:d('ICP–MS 等元素信号 + 标准与空白','校正空白及仪器漂移 → 处理内标和校准曲线 → 按质量或体积归一化 → 比较元素分布与组织背景','元素浓度表，必须注明干重、鲜重或体积等分母。','消解和污染控制；基体及谱干扰；样本质量分母一致','元素总量分析与化学形态分析不同；总铁含量不能指出它绑定在哪种分子上。','xcms','units'),
 redoxomics:d('差异化学标记 MS + 样本处理对照','及时固定原始氧化状态 → 按还原/氧化状态分步标记 → 鉴定位点并配对信号 → 联合总蛋白解释氧化还原变化','位点相关状态与相对定量；不同氧化形式需要适配化学策略。','制备人工氧化；标记完全性；总蛋白背景','总氧化指标、位点红氧蛋白组和特定修饰检测具有不同信息粒度。','ms','ptm'),
 microbiomics:d('16S / ITS FASTQ + 样本表 + 阴性对照','去引物并检查读段质量 → 去噪去嵌合体得到 ASV → 分配分类并构建特征表 → 分析多样性和组成差异','ASV×样本计数与分类表；ASV 不能一律当作一个物种。','低生物量污染；测序深度与引物偏倚；组成数据的分母效应','扩增子侧重标记分类，shotgun 宏基因组还可分析更广的功能潜力。','qiime','taxa'),
 metagenomics:d('shotgun DNA + 宿主参考 + 数据库','质控并去宿主读段 → 做分类谱或组装 → 注释基因并进行可选分箱 → 比较功能潜力及基因组质量','物种/基因家族丰度、contig、MAG；分类与组装是可选互补路线。','宿主污染；MAG 完整度和污染度；数据库版本与未注释序列','read-based 分类适合快速谱分析；assembly-based 路线可研究基因组背景。','tax','taxa'),
 metatranscriptomics:d('群落 RNA + rRNA/宿主参考 + 可选 DNA','检查 RNA 与有效读段 → 去除 rRNA 和宿主信号 → 定量功能基因或转录本 → 结合 DNA 丰度与群落组成解释','功能转录计数；总体变化可能来自成员比例或成员内表达。','rRNA 残留；RNA 保存与降解；分母及群落组成变化','宏基因组给功能潜力，宏转录组给采样时的 RNA 活动线索，二者需配对比较。','rnaseq','counts'),
 metaproteomics:d('群落 MS + 匹配宏基因组蛋白库','构建与样本相关的搜索库 → 鉴定肽段并控制错误率 → 处理共享肽的分类归属 → 汇总功能并比较蛋白证据','肽段、分类与功能表；数据库越大不等于鉴定越可靠。','搜索库冗余；跨物种共享肽；低丰度与动态范围','分类独有肽支持特异来源，共享肽更适合保守的功能或高层级汇总。','ms','peptides'),
 viromics:d('病毒富集或全样本序列 + 阴性对照','核对 DNA/RNA 建库范围 → 质控并处理宿主背景 → 组装或比对候选病毒序列 → 检查完整性和来源后报告','病毒候选序列、覆盖与分类；测到核酸不证明活病毒存在。','低量污染与试剂背景；参考库不完整；片段相似不等于完整病毒基因组','富集提高某些病毒信号但引入选择偏倚，全样本测序覆盖逻辑不同。','tax','coverage'),
 'singlecell-omics':d('细胞条码/UMI 读段 + 供者元数据','生成基因×细胞矩阵 → 识别低质量、环境 RNA 与双细胞 → 标准化降维聚类并注释 → 按供者设计比较组成或表达','AnnData / Seurat 对象、UMAP、标记表；可按供者和类型汇总 pseudobulk。','基因数和线粒体比例需结合组织；不能只按固定阈值机械筛；大量细胞不能替代供者重复','scRNA 与 snRNA 的细胞质覆盖及偏倚不同；整合不能抹去真实生物差异。','sc','counts'),
 'spatial-omics':d('表达矩阵 + 坐标 + 组织图像','检查组织覆盖和图像质量 → 对齐坐标、分割或汇总 spot → 分析区域与空间变异 → 结合细胞参考及邻域提出解释','空间表达对象、区域标签与邻域结果；坐标单位和分辨率必须保留。','配准误差；spot 混合与分割错误；切片和动物的重复层级','成像与捕获测序平台在靶标覆盖、分辨率与灵敏度间取舍。','sc','spatial'),
 immunomics:d('免疫表达/表型/受体/HLA 肽数据','分别质控各测量层 → 注释免疫细胞或受体 → 关联克隆、状态与呈递线索 → 用特异性和功能实验检验','多层证据表；受体序列、抗原结合与功能响应不能互相替代。','取样与处理激活；抗体背景；克隆定义及稀有细胞采样','免疫组学是问题组织方式，既可测细胞状态，也可测受体与呈递肽。','airr','clones'),
 phenomics:d('多通道图像 / 生理指标 + 干预表','检查成像与样本质量 → 分割细胞及亚细胞结构 → 提取形态和纹理特征 → 校正批次并比较表型谱','细胞×特征矩阵、形态嵌入和候选相似干预。','照明与焦距；密度和死亡率；训练验证按独立实验划分','人工指标易解释，高维图像特征覆盖广；相似表型需机制验证。','sc','features'),
 exposomics:d('化学谱 + 暴露记录 + 时间与协变量','检查空白与检测限 → 注释并量化化学特征 → 对齐采样时间与协变量 → 研究混合暴露关联并验证','暴露特征×样本表与关联结果，明确时间窗口。','近期与长期暴露区分；混杂与反向因果；多重检验','外部暴露记录与体内化学测量互补，单次检出不代表终生累积剂量。','xcms','features'),
 perturbomics:d('gRNA / 药物身份 + RNA/表型矩阵','检查扰动分配和效率 → 比较非靶向及阳性对照 → 按设计估计干预响应 → 独立向导或救援复核','扰动×基因/表型效应矩阵，附置信度及对照。','多重感染和错误分配；一般毒性与细胞周期；供者和实验批次','pooled 筛查依赖身份读取，arrayed 实验保留孔位；不同读出解释不同层面。','sc','network'),
 organellomics:d('分级/定位组学 + 区室标记','检查分离纯度与回收 → 定量各组分分子丰度 → 比较定位轮廓与标记 → 区分重定位和总体数量变化','蛋白×组分丰度轮廓及定位候选。','区室交叉污染；细胞器数量改变；破裂及分离造成重分布','分级提供丰度分布，成像与邻近标记补充空间证据。','ms','profiles'),
 pharmacogenomics:d('基因型/单倍型 + 药物响应研究数据','检查分型覆盖与相位 → 结合适用等位定义注释 → 控制协变量研究响应关联 → 在独立人群和证据框架验证','基因型、单倍型及研究关联；不直接生成个人用药处方。','群体结构；合并用药与剂量；参考版本及复杂位点覆盖','候选位点分型与全基因组关联覆盖不同；关联证据需考虑人群适用性。','variant','variant'),
 nutrigenomics:d('营养干预多组学 + 依从性和时间表','核对餐前餐后与配对 → 各模态独立质控 → 建立个体和时间相关模型 → 联系营养响应与表型验证','分子时间轨迹及干预相关效应，明确个体重复测量。','采样状态与时点；饮食记录和依从性；个体重复测量相关性','交叉设计与平行设计的分析不同，长期饮食和短期餐后反应不能混同。','deseq','profiles'),
 toxicogenomics:d('剂量×时间设计 + 多组学/功能终点','检查对照与实际暴露 → 量化分子和表型变化 → 联合分析剂量时间响应 → 区分适应与损伤并验证','剂量响应、时间轨迹和功能证据。','高剂量一般毒性；批次与细胞数；体外体系和实际暴露差异','分子敏感响应与真实功能损伤不同；不能把任一差异基因当作风险结论。','deseq','profiles'),
 'singlecell-atac':d('fragments.tsv.gz + 条码 + 基因组注释','按核检查 TSS / 片段数 / 双细胞 → 构建峰×细胞矩阵 → TF-IDF / LSI 后聚类及注释 → 分析差异峰和候选 motif','片段文件、稀疏峰矩阵与细胞注释；gene activity 是代理量。','TSS 富集与核小体信号；峰集合选择；稀疏性和深度影响降维','scATAC 测开放状态，scCUT&Tag 测靶标关联；RNA 联合提供互补身份信息。','signac','peaks'),
 'immune-repertoire':d('VDJ contig / AIRR 表 + 可选 RNA 条码','识别序列并检查 productive 链 → 核对链配对及多链情况 → 定义克隆并统计频率和多样性 → 关联表达状态并验证特异性','AIRR 格式序列、克隆型及频数；分母可以是细胞数或读段数。','双细胞和多链；克隆定义对结果的影响；采样深度与不同供者区分','bulk 库覆盖深，单细胞库保留链配对与状态，二者频数单位可能不同。','airr','clones'),
 'singlecell-multiome':d('RNA / ATAC / ADT 矩阵 + 共同条码','分别进行模态质控 → 按条码核对配对与缺失 → 计算适配的表示与联合邻域 → 对照单模态解释整合结果','多模态对象及联合图；每种模态仍保留自己的测量单位。','条码错配；抗体背景或 ATAC 稀疏性；整合结果是否保留真实差异','WNN 对细胞学习模态权重；原始数值直接拼接无法替代适配的预处理。','wnn','pairing')
};
export const priorityIds=['genomics','cancer-genomics','transcriptomics','isoform-omics','smallrna-omics','epigenomics','chromatinomics','methylomics','threed-genomics','singlecell-omics','singlecell-atac','singlecell-multiome','spatial-omics','immune-repertoire','proteomics','phosphoproteomics','metabolomics','microbiomics','metagenomics','metatranscriptomics'];
export const analysisQuestions=Object.fromEntries(Object.entries(analysis).map(([id,a],index)=>{const other=Object.values(analysis)[(index+3)%Object.keys(analysis).length],dataAnswer=index%2,caseAnswer=(index+1)%2,[prompt,correct,wrong,reason]=caseQuestions[id];return [id,[
 {id:'data-unit',prompt:'本方向这条路线的输出，哪项描述匹配？',options:dataAnswer?[other.result,a.result]:[a.result,other.result],answer:dataAnswer,reasons:dataAnswer?['这是另一测量路线的输出，请核对本方向的坐标与单位。','正确，输出类型与测量对象相对应。']:['正确，输出类型与测量对象相对应。','这是另一测量路线的输出，请核对本方向的坐标与单位。'],hint:'回看生信分析的输入、结果与技术对比。',level:'数据与单位'},
 {id:'interpretation',prompt,options:caseAnswer?[wrong,correct]:[correct,wrong],answer:caseAnswer,reasons:caseAnswer?['需要再区分测量与解释。'+reason,'正确。'+reason]:['正确。'+reason,'需要再区分测量与解释。'+reason],hint:a.compare,level:'研究情境判断'}
 ]];}));
